// Reads the pstack /statechart output in docs/statecharts/<flow>/charts/:
//   <config>.mmd         the chart the checker drew (Mermaid stateDiagram-v2)
//   <config>.report.md   what TLC found: each broken rule and its shortest path
// and the plain-words rules from the flow's verify skill in .claude/skills/.
// These files are generated by the checker and never edited by hand; this only reads them.

import fs from 'node:fs'
import path from 'node:path'

const MARKS = new Set(['breaks', 'mayBreak', 'bugPath', 'repeats'])

// Mermaid label escapes written by pstack: "#34;" in labels, "ﬂ°°34¶ß" in the title.
const decode = (s) =>
  s
    .replace(/#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/ﬂ°°(\d+)¶ß/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/⁠/g, '')

export function parseChart(text) {
  const lines = text.split(/\r?\n/)
  let i = 0
  let title = null
  if (lines[0]?.trim() === '---') {
    for (i = 1; i < lines.length && lines[i].trim() !== '---'; i++) {
      const m = lines[i].match(/^title:\s*(.*)$/)
      if (m) title = decode(JSON.parse(m[1]))
    }
    i++
  }
  const states = new Map()
  const legend = new Map()
  const edges = []
  const starts = []
  const stack = []
  const region = () => stack.filter((s) => s.id !== 'legend' && s.id !== 'all').map((s) => s.name).join(' / ') || null
  const inLegend = () => stack.some((s) => s.id === 'legend')
  for (; i < lines.length; i++) {
    const t = lines[i].trim()
    if (!t || t === 'stateDiagram-v2' || t === '--' || t.startsWith('direction ') || t.startsWith('classDef ')) continue
    let m
    if ((m = t.match(/^state "(.*)" as (\S+) \{$/))) stack.push({ id: m[2], name: decode(m[1]) })
    else if (t === '}') stack.pop()
    else if ((m = t.match(/^(\S+) --> (\S+)(?:: (.*))?$/))) {
      if (m[1] === '[*]') starts.push(m[2])
      else edges.push({ from: m[1], to: m[2], label: m[3] ? decode(m[3]) : '' })
    } else if ((m = t.match(/^class (\S+) (\S+)$/))) {
      const [, id, cls] = m
      if (legend.has(id)) legend.get(id).cls = cls
      else {
        const s = states.get(id)
        if (!s) continue
        if (MARKS.has(cls)) s.marks.push(cls)
        else s.group = cls
      }
    } else if ((m = t.match(/^(\S+): (.*)$/))) {
      if (inLegend()) legend.set(m[1], { label: decode(m[2]), cls: null })
      else states.set(m[1], { id: m[1], label: decode(m[2]), group: null, marks: [], region: region() })
    }
  }
  const groups = {}
  for (const s of states.values()) if (s.group) groups[s.group] = true
  const legendList = [...legend.values()].filter((l) => l.cls)
  for (const l of legendList) if (!MARKS.has(l.cls)) groups[l.cls] = l.label
  return { title, states: [...states.values()], edges, starts, legend: legendList }
}

// Splits "the visitor sends the form: Turned away: the page was hidden" at the colon
// after which a known state label follows; state labels can contain ": " too.
function splitStep(line, known) {
  const at = []
  for (let k = line.indexOf(': '); k !== -1; k = line.indexOf(': ', k + 1)) at.push(k)
  for (const k of at) if (known.has(line.slice(k + 2))) return { step: line.slice(0, k), state: line.slice(k + 2) }
  if (known.has(line)) return { step: '', state: line }
  const k = at.at(-1)
  return k === undefined ? { step: '', state: line } : { step: line.slice(0, k), state: line.slice(k + 2) }
}

export function parseReport(text, knownLabels = new Set()) {
  const lines = text.split(/\r?\n/)
  const out = { module: null, summary: [], breaks: [], holds: [], notChecked: [], other: [] }
  let section = null
  let bug = null
  for (const raw of lines) {
    const t = raw.trim()
    if (!t) continue
    let m
    if ((m = t.match(/^# (.+)$/))) {
      out.module = m[1]
      continue
    }
    if ((m = t.match(/^## (.+?) breaks$/))) {
      bug = { rule: m[1], path: [], loop: null, note: null }
      out.breaks.push(bug)
      section = 'bug'
      continue
    }
    if (/^## Rules that hold$/.test(t)) {
      section = 'holds'
      continue
    }
    if (/^## Rules not checked$/.test(t)) {
      section = 'notChecked'
      continue
    }
    if (/^## /.test(t)) {
      section = 'other'
      out.other.push(t.slice(3))
      continue
    }
    if (section === null) out.summary.push(t)
    else if (section === 'bug') {
      if ((m = t.match(/^(\d+)\. (.*)$/))) {
        const n = Number(m[1])
        const part = n === 0 ? { step: '', state: m[2] } : splitStep(m[2], knownLabels)
        bug.path.push(part)
      } else if (/forever\.$/.test(t)) bug.loop = t
      else bug.note = t
    } else if (section === 'holds') out.holds.push(...t.split(/,\s*/))
    else if (section === 'notChecked') out.notChecked.push(t)
  }
  return out
}

export function parseSkill(text, name) {
  const rules = {}
  let inRules = false
  let leftOut = null
  for (const line of text.split(/\r?\n/)) {
    if (/^##\s+Rules\b/.test(line)) inRules = true
    else if (/^##\s/.test(line)) inRules = false
    let m
    if (inRules && (m = line.match(/^\|\s*`([^`]+)`\s*\|\s*(.+?)\s*\|\s*$/))) rules[m[1]] = m[2]
    if ((m = line.match(/^Left out:\s*(.+)$/))) leftOut = m[1]
  }
  return { name, rules, leftOut }
}

const CURRENT = (name) => (/^today\b|^fixed\b|^now\b|^current\b/.test(name) ? 0 : /^before\b/.test(name) ? 2 : 1)

export function loadFlows(root, folder) {
  const base = path.join(root, folder)
  if (!fs.existsSync(base)) return { folder, flows: [] }
  const skillsDir = path.join(root, '.claude', 'skills')
  const skills = fs.existsSync(skillsDir)
    ? fs
        .readdirSync(skillsDir)
        .map((d) => path.join(skillsDir, d, 'SKILL.md'))
        .filter((f) => fs.existsSync(f))
        .map((f) => ({ name: path.basename(path.dirname(f)), text: fs.readFileSync(f, 'utf8') }))
    : []
  const flows = []
  for (const id of fs.readdirSync(base).sort()) {
    const dir = path.join(base, id)
    const chartsDir = path.join(dir, 'charts')
    if (!fs.statSync(dir).isDirectory() || !fs.existsSync(chartsDir)) continue
    const files = fs.readdirSync(chartsDir)
    const names = new Set()
    for (const f of files) {
      if (f.endsWith('.report.md')) names.add(f.slice(0, -'.report.md'.length))
      else if (f.endsWith('.mmd')) names.add(f.slice(0, -'.mmd'.length))
    }
    const skillFile = skills.find((s) => s.text.includes(`${folder}/${id}/`))
    const skill = skillFile ? parseSkill(skillFile.text, skillFile.name) : null
    const configs = [...names]
      .sort((a, b) => CURRENT(a) - CURRENT(b) || a.localeCompare(b))
      .map((name) => {
        const mmd = path.join(chartsDir, name + '.mmd')
        const rpt = path.join(chartsDir, name + '.report.md')
        const chart = fs.existsSync(mmd) ? parseChart(fs.readFileSync(mmd, 'utf8')) : null
        const known = new Set(chart ? chart.states.map((s) => s.label) : [])
        const report = fs.existsSync(rpt) ? parseReport(fs.readFileSync(rpt, 'utf8'), known) : null
        return {
          id: name,
          chart,
          report,
          files: [mmd, rpt].filter((f) => fs.existsSync(f)).map((f) => path.relative(root, f).split(path.sep).join('/')),
        }
      })
    const spec = fs.readdirSync(dir).find((f) => f.endsWith('.tla'))
    const title = configs.find((c) => c.chart?.title)?.chart.title || id
    flows.push({
      id,
      title,
      folder: `${folder}/${id}`,
      spec: spec ? `${folder}/${id}/${spec}` : null,
      view: fs.existsSync(path.join(dir, 'view.mts')) ? `${folder}/${id}/view.mts` : null,
      skill,
      configs,
    })
  }
  return { folder, flows }
}
